32	\subsection{对比视角：为什么 OS-World 更接近生产问题}
33	\begin{table}[H]
34	\centering
35	\begin{tabular}{p{3.2cm}p{3.7cm}p{3.8cm}}
36	\toprule
37	\textbf{维度} & \textbf{传统 Web 基准} & \textbf{OS-World} \\
38	\midrule
39	环境覆盖 & 主要网页域 & 网页 + 桌面应用 + 系统交互 \\
40	任务形态 & 偏导航与表单 & 跨应用、多步骤、开放式流程 \\
41	评测方式 & 页面结果导向 & 脚本验证 + 部分完成奖励 \\
42	扩展能力 & 新任务构建成本较高 & 支持系统化新增任务与配置 \\
43	工程适配 & 偏离线评测 & 开发、训练、评测一体化 \\
44	\bottomrule
45	\end{tabular}
46	\caption{OS-World 并非替代所有基准，而是补齐 ``真实计算机任务'' 的核心空缺}
47	\end{table}
